// Entry point for the Worker: the OpenNext handler wrapped in an edge cache for anonymous GET requests.
// @ts-expect-error: generated by `opennextjs-cloudflare build`, so it has no types and does not exist before a build.
import openNextWorker from "./.open-next/worker.js";
import { serveWithEdgeCache, type EdgeCache } from "./lib/cache/edgeResponseCache";

// @ts-expect-error: generated by `opennextjs-cloudflare build`.
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

interface WorkerEnv {
  CF_VERSION_METADATA?: { id: string };
}

interface WorkerContext {
  waitUntil(promise: Promise<unknown>): void;
}

interface OpenNextWorker {
  fetch(request: Request, env: WorkerEnv, ctx: WorkerContext): Promise<Response>;
}

const handler: OpenNextWorker = openNextWorker;

// `caches.default` exists only in the Workers runtime, so the DOM typings do not describe it.
function getEdgeCache(): EdgeCache {
  return (caches as unknown as { default: EdgeCache }).default;
}

const worker = {
  fetch(request: Request, env: WorkerEnv, ctx: WorkerContext): Promise<Response> {
    const url = new URL(request.url);

    // Block internal cache namespace and direct probe requests
    if (url.pathname.startsWith("/__edge-cache")) {
      return Promise.resolve(
        new Response("Not Found", {
          status: 404,
          headers: { "Content-Type": "text/plain; charset=utf-8" },
        })
      );
    }

    // Stealth sitemap endpoint for Google Search Console (hidden from client bundles)
    if (url.pathname === "/dashcse5323.xml") {
      const internalUrl = new URL("/api/sitemaps/pages.xml", request.url);
      const internalReq = new Request(internalUrl.toString(), request);
      return serveWithEdgeCache(internalReq, env.CF_VERSION_METADATA?.id, getEdgeCache(), ctx, () =>
        handler.fetch(internalReq, env, ctx)
      );
    }

    // Block standard sitemap discovery and internal API probes
    if (
      url.pathname === "/sitemap.xml" ||
      url.pathname === "/sitemap_index.xml" ||
      url.pathname === "/sitemaps/pages.xml" ||
      url.pathname.startsWith("/api/sitemaps")
    ) {
      return Promise.resolve(
        new Response("Not Found", {
          status: 404,
          headers: { "Content-Type": "text/plain; charset=utf-8" },
        })
      );
    }

    return serveWithEdgeCache(request, env.CF_VERSION_METADATA?.id, getEdgeCache(), ctx, () =>
      handler.fetch(request, env, ctx)
    );
  },
};

export default worker;
